from functools import lru_cache

class Solution:
    def coinChange(self, coins, amount):
        @lru_cache(None)
        def go(a):
            if a == 0:
                return 0
            best = float('inf')
            for c in coins:
                if c <= a:
                    best = min(best, go(a - c) + 1)
            return best
        r = go(amount)
        return -1 if r == float('inf') else r
